+                @if (status == "completed")
+                {
+                    <button type="button" class="btn btn-link p-0 text-decoration-none" @onclick="() => OnStepClicked.InvokeAsync(stepIndex)">
+                        <span class="step-circle bg-success text-white d-inline-flex align-items-center justify-content-center rounded-circle" style="width:32px;height:32px;">✓</span>
+                        <div class="small mt-1 text-success fw-semibold">@StepNames[stepIndex]</div>
+                    </button>
+                }
+                else if (status == "active")
+                {
+                    <span class="step-circle bg-primary text-white d-inline-flex align-items-center justify-content-center rounded-circle" style="width:32px;height:32px;">@(stepIndex + 1)</span>
+                    <div class="small mt-1 text-primary fw-semibold">@StepNames[stepIndex]</div>
+                }
+                else
+                {
+                    <span class="step-circle bg-secondary text-white d-inline-flex align-items-center justify-content-center rounded-circle opacity-50" style="width:32px;height:32px;">@(stepIndex + 1)</span>
+                    <div class="small mt-1 text-muted">@StepNames[stepIndex]</div>
+                }
+            </li>
+        }
+    </ol>
+</nav>
+
+@code {
+    [Parameter, EditorRequired] public int CurrentStep { get; set; }
+    [Parameter, EditorRequired] public IReadOnlyList<string> StepNames { get; set; } = [];
+    [Parameter, EditorRequired] public EventCallback<int> OnStepClicked { get; set; }
+
+    private string GetStepStatus(int index)
+    {
+        if (index < CurrentStep) return "completed";
+        if (index == CurrentStep) return "active";
+        return "future";
+    }
+}
+

