@using sv_74c37afb9b96496e8fc2a407f06731ff.Models

<h4 class="mb-3">Personal Information</h4>

@if (!string.IsNullOrEmpty(_error))
{
    <div class="alert alert-danger">@_error</div>
}

<div class="row g-3">
    <div class="col-md-6">
        <label class="form-label">Full Name <span class="text-danger">*</span></label>
        <input type="text" class="form-control" @bind="_fullName" />
    </div>
    <div class="col-md-6">
        <label class="form-label">Email <span class="text-danger">*</span></label>
        <input type="email" class="form-control" @bind="_email" />
    </div>
    <div class="col-md-6">
        <label class="form-label">Phone <span class="text-danger">*</span></label>
        <input type="text" class="form-control" @bind="_phone" />
    </div>
    <div class="col-md-6">
        <label class="form-label">Address <span class="text-danger">*</span></label>
        <input type="text" class="form-control" @bind="_address" />
    </div>
</div>

<div class="d-flex justify-content-end mt-4">
    <button type="button" class="btn btn-primary" @onclick="HandleNext" disabled="@_validating">
        @if (_validating)
        {
            <span class="spinner-border spinner-border-sm me-1"></span>
        }
        Next
    </button>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfo Model { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<PersonalInfo> OnNext { get; set; }
    [Parameter, EditorRequired] public IApplicationService ApplicationService { get; set; } = default!;

    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";
    private string? _error;
    private bool _validating;

    protected override void OnParametersSet()
    {
        _fullName = Model.FullName;
        _email = Model.Email;
        _phone = Model.Phone;
        _address = Model.Address;
    }

    private async Task HandleNext()
    {
        _error = null;

        if (string.IsNullOrWhiteSpace(_fullName) || string.IsNullOrWhiteSpace(_email)
            || string.IsNullOrWhiteSpace(_phone) || string.IsNullOrWhiteSpace(_address))
        {
            _error = "All fields are required.";
            return;
        }

        _validating = true;
        try
        {
            var emailValid = await ApplicationService.ValidateEmailAsync(_email.Trim());
            if (!emailValid)
            {
                _error = "The email address is not valid.";
                return;
            }
        }
        finally
        {
            _validating = false;
        }

        await OnNext.InvokeAsync(new PersonalInfo(_fullName.Trim(), _email.Trim(), _phone.Trim(), _address.Trim()));
    }
}

