@using sv_74c37afb9b96496e8fc2a407f06731ff.Models

<h4 class="mb-3">Work History</h4>

@if (!string.IsNullOrEmpty(_error))
{
    <div class="alert alert-danger">@_error</div>
}

@for (int i = 0; i < _entries.Count; i++)
{
    var index = i;
    <WorkEntryForm Entry="_entries[index]" Index="index" CanRemove="_entries.Count > 1"
                   OnChanged="e => HandleEntryChanged(index, e)"
                   OnRemove="() => RemoveEntry(index)" />
}

<button type="button" class="btn btn-outline-primary mb-3" @onclick="AddEntry">
    + Add Another Position
</button>

<div class="d-flex justify-content-between mt-3">
    <button type="button" class="btn btn-secondary" @onclick="OnBack">Back</button>
    <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntry> Entries { get; set; } = [];
    [Parameter, EditorRequired] public EventCallback<List<WorkEntry>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private List<WorkEntry> _entries = [];
    private string? _error;

    protected override void OnParametersSet()
    {
        _entries = Entries.Select(e => e).ToList();
        if (_entries.Count == 0)
            _entries.Add(new WorkEntry("", "", default, null, ""));
    }

    private void HandleEntryChanged(int index, WorkEntry updated) => _entries[index] = updated;
    private void RemoveEntry(int index) => _entries.RemoveAt(index);
    private void AddEntry() => _entries.Add(new WorkEntry("", "", default, null, ""));

    private async Task HandleNext()
    {
        _error = null;
        foreach (var entry in _entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) || entry.StartDate == default)
            {
                _error = "Each position requires a company name, job title, and start date.";
                return;
            }
        }
        await OnNext.InvokeAsync(_entries);
    }
}

