@using sv_74c37afb9b96496e8fc2a407f06731ff.Models

<h4 class="mb-3">References</h4>

@if (!string.IsNullOrEmpty(_error))
{
    <div class="alert alert-danger">@_error</div>
}

@for (int i = 0; i < _references.Count; i++)
{
    var index = i;
    <ReferenceForm Reference="_references[index]" Index="index" CanRemove="_references.Count > 1"
                   OnChanged="e => HandleReferenceChanged(index, e)"
                   OnRemove="() => RemoveReference(index)" />
}

@if (_references.Count < 3)
{
    <button type="button" class="btn btn-outline-primary mb-3" @onclick="AddReference">
        + Add Reference
    </button>
}

<div class="d-flex justify-content-between mt-3">
    <button type="button" class="btn btn-secondary" @onclick="OnBack">Back</button>
    <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter, EditorRequired] public List<Reference> References { get; set; } = [];
    [Parameter, EditorRequired] public EventCallback<List<Reference>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private List<Reference> _references = [];
    private string? _error;

    protected override void OnParametersSet()
    {
        _references = References.Select(r => r).ToList();
        if (_references.Count == 0)
        {
            _references.Add(new Reference("", "", "", ""));
            _references.Add(new Reference("", "", "", ""));
        }
    }

    private void HandleReferenceChanged(int index, Reference updated) => _references[index] = updated;
    private void RemoveReference(int index) => _references.RemoveAt(index);
    private void AddReference()
    {
        if (_references.Count < 3)
            _references.Add(new Reference("", "", "", ""));
    }

    private async Task HandleNext()
    {
        _error = null;
        foreach (var r in _references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                _error = "All reference fields are required.";
                return;
            }
        }
        await OnNext.InvokeAsync(_references);
    }
}

